function buildSignCard(code) {
  const meta = SIGN_META[code] || ["Знак " + code, "Описание знака"];
  return {
    id: "sign-" + code,
    type: "sign",
    code,
    title: "Знак " + code,
    subtitle: meta[0],
    description: meta[0] + ". " + meta[1] + ".",
    image: signImg(code),
  };
}

